    ('b7acf3a4-334a-579c-a4d0-a712b44b6d65'::uuid, 'Quiz — Mi, mío, el mío : trois emplois', 'Espagnol', '2de', 'Les possessifs', '2d7b88c2-d0d5-5ae0-b732-66b96a86615c'::uuid),
    ('bb145049-357e-50b7-b0d8-009666ac1b2f'::uuid, 'Quiz — Que, quien, el que, cuyo', 'Espagnol', '2de', 'Les pronoms relatifs', '0a752ff8-30f9-5f37-b4d1-037dadc1f623'::uuid),
