    ('77692ebb-4770-5855-a00d-02041d4c95ef'::uuid, 'Quiz — E → i : la famille de pedir', 'Espagnol', '2de', 'Les verbes à affaiblissement', 'db4f8edc-c4cb-5805-bb14-4faaf3ad3c21'::uuid),
