    ('9dbfa6e5-5154-5b5f-9858-c96da5a49178'::uuid, 'Quiz — Estar + gérondif, et les tournures de durée', 'Espagnol', '2de', 'Le gérondif', 'bfdf23af-ad93-5270-bbaf-8567833ac95f'::uuid),
    ('58569832-6ae2-56af-a869-8fb5bed507ff'::uuid, 'Quiz — Accord ou pas : la question qui tranche', 'Espagnol', '2de', 'Le participe passé', '119462d4-2efb-5c5e-b00d-fa22a307a0ca'::uuid),
